from pathlib import Path
import html,json,re,shutil
R=Path(__file__).resolve().parents[5];D=Path(__file__).resolve().parent;C=Path('/tmp/medina-source-cache/endocrinologie/E30')
assert not (D/'source-binding.json').exists(),'Final evidence sealed; never refresh automatically.'
assert 'VÉRITÉ OK' in (D/'research-gate.log').read_text()
ledger=json.loads((D/'source-ledger.json').read_text())['sources'];pops=[];summaries=[]
def w(k,label):return f'<button class="w" data-k="e30-{k}">{label}</button>'
def table(h,rows):return '<table class="t" data-e30-table="1"><thead><tr>'+''.join('<th>'+x+'</th>' for x in h)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in rr)+'</tr>' for rr in rows)+'</tbody></table>'
def pop(k,title,body):pops.append(f'<template data-pop="e30-{k}" data-title="{html.escape(title,quote=True)}">{body}</template>')
def sec(k,title,body,summary):
 a='e30-'+str(k);pk='pareto-'+a;summaries.append(f'<template data-pop="{pk}" data-title="Essentiel — {html.escape(title,quote=True)}"><p>{summary}</p><p class="ratio" data-cover="{a}"></p></template>')
 return f'<section class="ilot" id="{a}"><h2><span class="n">{k}</span>{title}</h2>{body}<div class="key"><b>À retenir.</b> {summary}</div><button class="pareto-btn ui" data-k="{pk}">Essentiel de cette partie</button></section>'
S=[]
S.append(sec(1,'Le signe, son âge et son tempo','''<p>Une fille fictive de six ans et demi développe des seins. Un garçon fictif de quatorze ans et demi s’inquiète de ne pas changer comme ses camarades. Les deux situations justifient une évaluation, mais ni une injection automatique ni une simple rassurance sur l’histoire familiale. L’âge oriente ; le tempo, la croissance, les autres signes et le contexte donnent leur sens [S3, S5, S7].</p><p>Chez la fille, le début central est généralement marqué par le développement mammaire ; chez le garçon, par l’augmentation du volume testiculaire. Une pilosité pubienne isolée peut provenir de la surrénale et ne prouve pas la même activation. Une ménarche est un signe plus tardif, pas le début habituel du processus [S5, S7].</p><p>Le raisonnement rejoint les situations PROFILES de croissance et puberté inhabituelles, ainsi que l’examen génital expliqué et proportionné. Le rapprochement avec E30 est pédagogique, sans correspondance officielle entre code et question fédérale. Les vignettes sont originales [S20].</p>''','Un âge inhabituel déclenche une enquête. La progression et la croissance distinguent souvent mieux les hypothèses qu’un signe isolé [S3, S5, S7].'))
S.append(sec(2,'Définition et périmètre de la leçon','''<p>E30 désigne les anomalies de la puberté non classées ailleurs. Le cours distingue retard, précocité, variantes isolées et anomalie encore non précisée. Il enseigne aussi les diagnostics voisins nécessaires au raisonnement, sans prétendre les faire tous entrer dans E30 ni modifier leurs autres chapitres [S1, S2].</p><p>La puberté centrale correspond à la réactivation de l’axe hypothalamo-hypophyso-gonadique. Une production périphérique de stéroïdes sexuels peut provoquer certains signes sans cette activation. Le retard peut refléter une maturation constitutionnelle, une inhibition fonctionnelle liée à une maladie ou à un déficit énergétique, ou un déficit permanent d’origine centrale ou gonadique [S5–S7].</p><p>La distinction clinique et le code ne sont pas la même question. Les notes allemandes de la modification 2024 excluent la précocité centrale de E30.1 vers E22.8 ; elles excluent aussi l’hyperplasie congénitale surrénale et le syndrome de McCune-Albright vers leurs catégories. Ces notes sont confrontées aux libellés suisses locaux, sans certification du codage individuel 2026 [S1, S2].</p>''','Le mécanisme et l’étiologie guident les soins. « Précoce » ne signifie pas nécessairement E30.1 après diagnostic précis [S1, S2, S7].'))
S.append(sec(3,'Épidémiologie suisse puis européenne','''<p>Les études longitudinales zurichoises publiées en 1983 décrivaient 142 filles et 142 garçons suivis dans la période 1954–1980. Chez les filles, la ménarche moyenne était à 13,4 ans, avec écart-type d’un an ; la durée et l’ordre de certains signes variaient largement. Ce sont des données historiques de développement, pas des normes suisses actuelles ou une incidence des anomalies E30 [S9, S10].</p><p>Une cohorte nationale danoise publiée en 2020 comptait 8596 enfants enregistrés entre 1998 et 2017 avec précocité centrale, thélarche prématurée ou adrénarche prématurée. Elle ne comptait donc pas seulement des formes centrales. Dans le groupe défini par le registre comme d’origine danoise, l’incidence diagnostique annuelle moyenne de forme centrale était de 9,2 pour 10 000 filles et 0,9 pour 10 000 garçons [S21].</p><p>Les codes n’avaient pas tous été validés sur dossier, et une suspicion initiale pouvait ne pas avoir été corrigée après exploration. L’adressage et la sensibilisation ont pu évoluer. Ces limites empêchent de confondre taux d’enregistrement, mécanisme biologique et fréquence suisse actuelle [S21].</p><p>Les séries européennes de retard pubertaire sont souvent dominées par les garçons et les consultations spécialisées. Leurs proportions de retard constitutionnel ne deviennent pas une probabilité automatique pour tout adolescent. Aucune incidence suisse contemporaine de toute E30 et de chaque sous-groupe n’est établie dans les lectures [S5, S6].</p>''','Les cohortes suisses anciennes décrivent le développement ; les registres danois décrivent des diagnostics dans une période donnée. Aucun chiffre ne remplace une incidence suisse E30 non établie [S9, S10, S21].'))
S.append(sec(4,'Du fonctionnement normal au trouble','''<p>Le signal hypothalamique pulsatile stimule la sécrétion hypophysaire des gonadotrophines. Celles-ci activent les gonades et la production de stéroïdes sexuels. Le développement des caractères secondaires, la poussée staturale et la maturation osseuse sont liés, mais n’atteignent pas tous leur maximum au même moment [S5].</p><p>Dans le testicule, les cellules de Leydig produisent la testostérone en réponse au signal lutéinisant ; les cellules de Sertoli soutiennent le compartiment germinal et répondent au signal folliculostimulant. Dans l’ovaire, les cellules folliculaires coopèrent à la maturation et à la production de stéroïdes. L’inhibine freine surtout la sécrétion folliculostimulante ; ce n’est pas un raccourci selon lequel toute baisse de cette hormone fait directement baisser la testostérone [S5, S18, S19].</p><p>Les androgènes surrénaliens expliquent l’adrénarche : odeur corporelle, pilosité et acné peuvent apparaître sans gonadarche. À l’inverse, une activation gonadique centrale peut commencer avant que tous ces signes soient présents. La pilosité seule ne mesure donc pas l’état de l’axe central [S7].</p><p>Un excès précoce de stéroïdes peut accélérer croissance et âge osseux, puis réduire le potentiel statural. Le manque de stéroïdes peut retarder la poussée et compromettre l’acquisition osseuse. Les œstrogènes participent à la maturation des cartilages de croissance dans les deux sexes ; l’aromatisation de la testostérone compte aussi [S5].</p>''','Adrénarche et gonadarche sont deux processus. Une grande taille initiale n’exclut pas un risque de petite taille finale si la maturation est accélérée [S5, S7].'))
S.append(sec(5,'Classer les mécanismes et leurs causes',table(['Profil','Hypothèses','Élément utile'],[['Précoce central','Activation prématurée idiopathique, familiale ou liée à une atteinte neurologique','Progression des signes et réponse gonadotrope ; rechercher signes neurologiques.'],['Précoce périphérique','Kyste/tumeur gonadique, cause surrénale, hormone chorionique, exposition, mutation activatrice ou hypothyroïdie sévère','Stéroïdes élevés avec gonadotrophines freinées ; profil orienté et imagerie selon la cause.'],['Retard avec gonadotrophines élevées','Insuffisance gonadique, anomalie chromosomique ou séquelle acquise','Stéroïdes insuffisants et réponse hypophysaire élevée selon âge/stade.'],['Retard avec signal bas/inadapté','Retard constitutionnel, déficit central permanent ou inhibition fonctionnelle','Croissance, nutrition, maladie, autres axes, contexte néonatal et progression.'],['Signe isolé','Thélarche ou adrénarche prématurée, lipomastie','Examen du tissu, autres signes et évolution ; ne pas conclure sur la seule apparence.']])+'''<p>Une maladie cœliaque ou inflammatoire, une restriction alimentaire, une faible disponibilité énergétique, un exercice excessif, des médicaments et d’autres endocrinopathies peuvent freiner la maturation. Une croissance anormale ou l’arrêt de progression demande de reconsidérer un diagnostic constitutionnel présumé [S5, S6].</p><p>Une histoire familiale de puberté tardive n’exclut pas un déficit congénital, et une histoire de précocité n’exclut pas une lésion neurologique. Une cause déjà connue comme Turner, Klinefelter ou une anomalie surrénale garde son parcours propre [S2, S5–S7, S17].</p>''','La distinction central/périphérique et gonadique/centrale choisit les explorations ; l’histoire familiale oriente sans trancher [S5–S7].'))
S.append(sec(6,'Anamnèse : croissance, chronologie et vécu','''<p>Reconstituer l’âge du premier signe, sa vitesse, les saignements, la croissance et les changements récents. Relire les courbes plutôt que demander seulement « a-t-il grandi ? ». Préciser taille parentale, puberté des apparentés et antécédents de traitement. Une photo intime n’est pas nécessaire pour recueillir la chronologie [S3, S5, S7].</p><p>Rechercher céphalées, troubles visuels, crises, antécédents neurologiques, irradiation, chimiothérapie et exposition à des crèmes ou hormones de l’entourage. Dans le retard, préciser alimentation, poids, activité physique, maladie chronique, symptômes digestifs, médicaments et signes d’autres déficits. Micropénis, cryptorchidie bilatérale et trouble de l’odorat orientent vers un déficit central congénital, sans être toujours présents [S5–S7].</p><p>Chez la fille, préciser développement mammaire, cycles ou absence de règles et contexte gynécologique ; un saignement prépubère ne devient pas automatiquement une ménarche. Chez le garçon, l’augmentation testiculaire et la virilisation ne sont pas toujours parallèles [S5–S7, S16].</p><p>Demander ce qui préoccupe l’adolescent : décalage avec les pairs, harcèlement, image corporelle, anxiété et projet de vie. Expliquer les échanges confidentiels et leurs limites selon le cadre clinique ; adapter l’information et le consentement à la maturité. L’apparence ou le caryotype ne déterminent pas une identité de genre [S5].</p>''','La courbe et le tempo sont des données cliniques ; la détresse et les obstacles aux soins font aussi partie de l’indication de suivi [S3, S5].'))
S.append(sec(7,'Examen clinique et sémiologie',f'''<div data-semiology-clinical="E30"><p>La sémiologie commence par taille, poids, vitesse staturale, proportions, pression et état général. Décrire le développement avec les {w('stades','stades de Tanner et leur méthode')}, en distinguant seins, organes génitaux et pilosité. La pilosité ne remplace pas une mesure de développement gonadique [S5–S7].</p><p>Chez la fille, distinguer tissu mammaire et adiposité peut nécessiter une palpation expliquée. Chez le garçon, mesurer le volume testiculaire avec un outil connu et rechercher asymétrie, masse ou antécédent de cryptorchidie. Le seuil d’un orchidomètre n’est pas une conversion automatique d’un volume échographique [S5–S7].</p><p>L’examen génital est proportionné à la question, expliqué et réalisé avec accord approprié et respect de l’intimité. Réduire les répétitions et ne pas tirer de conclusion sur une activité sexuelle à partir de l’hymen. Les signes neurologiques et syndromiques sont recherchés selon l’hypothèse [S5, S7, S19].</p><p>Une morphologie seule ne confirme pas la cause. Les neuf volets de {w('semio','sémiologie fondamentale et analytique')} développent le lien entre signe, mécanisme, examen et décision ; aucune sensibilité chiffrée universelle de l’examen n’est inventée.</p></div>''','La méthode, le stade et le suivi donnent un sens au volume ou au signe. L’examen protège aussi l’intimité et la relation de soin [S5–S7].'))
S.append(sec(8,'Diagnostic : une séquence et des seuils contextualisés',f'''<p>Confirmer d’abord le signe et sa chronologie, apprécier progression et croissance, puis rechercher la cause. Les repères usuels de précocité sont avant huit ans chez la fille et neuf ans chez le garçon. L’absence de seins à treize ans ou de croissance testiculaire pubertaire à quatorze ans justifie une évaluation selon Endo-ERN ; un arrêt ou une progression inadéquate peut justifier une enquête sans attendre ces âges [S5, S7].</p><p>Le profil comprend les {w('gonadotrophines','gonadotrophines et stéroïdes sexuels')} avec âge, stade, horaire et méthode. Une valeur basse du signal lutéinisant ne suffit pas à exclure une activation centrale débutante. Les dosages peu sensibles et les fluctuations sont particulièrement importants au début [S5, S6].</p><p>Une stimulation peut aider : le guide danois 2025 cite comme indicatifs un pic lutéinisant &gt;5 unités internationales/L et/ou un rapport lutéinisant/folliculostimulant &gt;0,6 à trente minutes. Ce n’est pas un seuil universel ; des enfants de deux–trois ans avec thélarche isolée peuvent dépasser le pic sans forme centrale progressive [S7].</p><p>Dans le retard, le test ne distingue pas seul maturation constitutionnelle et déficit central permanent. L’évaluation longitudinale, les autres causes, les marqueurs et éventuellement la génétique spécialisée complètent le bilan. Le diagnostic constitutionnel reste une conclusion suivie, pas une étiquette rassurante fondée seulement sur la famille [S5, S6].</p>''','Le seuil choisit une exploration et garde sa méthode ; il ne remplace pas âge, progression et contexte [S5–S7].'))
S.append(sec(9,'Gravité, drapeaux rouges et imagerie',f'''<p>Céphalées inhabituelles ou progressives, troubles visuels, vomissements neurologiques, crises ou déficit focal imposent une évaluation rapide. Une virilisation très rapide, une masse ou une asymétrie testiculaire nette font rechercher une production périphérique ou une tumeur. Un saignement prépubère nécessite d’examiner aussi infection, corps étranger, traumatisme et situation de protection de l’enfant ; il ne doit pas être attribué sans examen à la puberté [S7, S17].</p><p>Le guide européen danois 2025 propose une imagerie cérébrale pour les filles centrales de moins de six ans, une discussion spécialisée à six–huit ans, et pour tous les garçons centraux avant neuf ans. Les recommandations italiennes publiées en 2024/2025 demandent aussi l’imagerie chez les garçons centraux [S6, S7].</p><p>Une revue européenne 2026 discute des données plus sélectives chez les garçons de huit–neuf ans sans signes neurologiques. Ses cohortes récentes excluent certains antécédents et ses propositions nécessitent validation ; elle reprend aussi une recommandation américaine 2026. Ce désaccord n’autorise ni à ignorer un drapeau rouge ni à exclure une lésion sur la famille seule. La {w('imagerie','décision d’imagerie actualisée')} appartient au parcours spécialisé [S17].</p><p>La FI Lucrin mentionne un scanner cérébral dans son bilan initial. Les sources cliniques privilégient le raisonnement par résonance magnétique ; ce libellé de produit n’impose pas une irradiation automatique. L’équipe confronte indication, urgence, méthode et FI [S6, S7, S11, S17].</p>''','Un signe neurologique, une progression explosive ou une masse change l’urgence. Les débats de dépistage d’une lésion ne concernent pas une situation avec drapeau rouge [S7, S17].'))
S.append(sec(10,'Traitement : parfois surveiller, parfois freiner ou induire',f'''<p>La cause et la conséquence guident la décision. Une variante isolée stable peut demander une surveillance plutôt qu’un médicament ; une production périphérique demande le traitement de sa cause. Les agonistes à action prolongée du signal hypothalamique suppriment l’activation centrale après une phase initiale de stimulation ; ils ne traitent pas automatiquement une source périphérique autonome [S5–S7].</p><p>Dans une précocité centrale progressive, le bénéfice statural est mieux établi pour les débuts très précoces. À six–huit ans chez la fille, tempo, âge osseux, taille attendue et vécu orientent une décision partagée ; tous les enfants n’ont pas le même bénéfice. Les FI {w('lucrin','Lucrin Dépôt 3,75 mg mensuel')} et {w('pamorelin','Pamorelin LA 22,5 mg')} précisent leurs indications, voies et intervalles, qui ne se substituent pas l’un à l’autre [S7, S11, S12].</p><p>Dans le retard, traiter d’abord les causes fonctionnelles accessibles et accompagner le vécu. En déficit permanent connu, une induction à un âge proche des pairs peut être envisagée sans attendre le seuil général de retard : environ onze ans chez la fille et douze ans chez le garçon dans les recommandations européennes, avec individualisation [S5].</p><p>L’estradiol est augmenté progressivement ; le protocole d’induction n’est pas le schéma d’une contraception combinée. La testostérone peut induire les caractères chez le garçon, mais ne restaure pas à elle seule croissance testiculaire et spermatogenèse en déficit central. L’alternative par gonadotropines et le projet de fertilité sont discutés. Les monographies distinguent {w('testoviron','l’énanthate suisse')}, {w('estradiol','l’induction œstrogénique et sa limite de produit')} et {w('undecanoate','l’undécanoate adulte')} [S5, S13–S15].</p>''','Surveiller, freiner et induire répondent à trois situations différentes. L’objectif est une maturation adaptée, pas une dose adulte immédiate [S5–S7].'))
S.append(sec(11,'Suivi, complications et pronostic','''<p>Le suivi documente taille, vitesse, poids, stade, effets attendus et indésirables, prise réelle et vécu. Sous suppression centrale, une progression persistante peut indiquer erreur de diagnostic, problème d’administration ou suppression insuffisante ; elle ne se corrige pas par un changement improvisé d’intervalle [S6, S7, S11, S12].</p><p>La FI Pamorelin prévoit des contrôles hormonaux un à deux mois après la première injection et la taille tous les trois–six mois. Les guides proposent différents rythmes d’âge osseux selon question et situation ; aucun intervalle unique n’est attribué à toutes les sources. En induction, un suivi clinique tous les trois–six mois adapte progression et tolérance [S5–S7, S12].</p><p>La précocité progressive peut compromettre la taille finale ; le retard prolongé avec déficit hormonal peut compromettre acquisition osseuse et bien-être. La prédiction de taille conserve ses incertitudes et ne promet pas des centimètres identiques à tout enfant. Une histoire de traitement ne prouve ni infertilité future ni fertilité garantie [S5–S7].</p><p>Après arrêt d’une suppression, le développement doit reprendre ; la famille connaît les raisons de recontacter le centre si l’évolution manque. Les déficits permanents nécessitent une transition vers la substitution adulte, l’éducation à l’autonomie et la discussion de fertilité. La décision d’arrêt confronte les limites des FI suisses et les critères cliniques, sans mélange caché d’âge chronologique et osseux [S5, S7, S11, S12].</p>''','Le suivi vérifie le sens de l’évolution et les effets. Une dose ou une date ne remplacent pas le contrôle de la maturation [S5, S7, S12].'))
S.append(sec(12,'Populations particulières et information','''<p>Chez le petit enfant, la minipuberté et la thélarche isolée modifient l’interprétation hormonale. Un pic stimulé qui serait évocateur chez un enfant plus âgé n’a pas automatiquement le même sens à deux–trois ans. Les dosages et leur lecture doivent être adaptés [S5, S7].</p><p>Chez l’enfant ayant un déficit connu, une anomalie chromosomique ou un traitement gonadotoxique, le suivi commence plus tôt. Une puberté spontanée initiale n’exclut pas une insuffisance secondaire de progression, notamment dans certains profils gonadiques. Taille petite ou grande et caryotype ne suffisent pas à prédire tous les besoins [S5].</p><p>En restriction alimentaire ou maladie inflammatoire, traiter la cause et les conséquences nutritionnelles est essentiel. Une induction ne remplace pas la restauration de santé générale. L’adolescent avec handicap ou difficultés cognitives reçoit une information et une éducation adaptées, avec soutien du réseau ; le besoin d’éducation à la santé sexuelle n’est pas effacé [S5, S6].</p><p>Grossesse possible, allaitement, maladie hépatique, rénale ou risque thromboembolique changent la vérification du produit. Les données adultes des FI ne sont pas des taux de risque pédiatriques. Un traitement hormonal substitutif n’est pas, par sa seule présence, un contraceptif. Confidentialité, consentement approprié et projet de vie accompagnent le traitement [S5, S11–S15].</p>''','L’âge, la cause connue, les autres maladies et les objectifs modifient le parcours ; les mêmes chiffres ne s’appliquent pas à tous [S5, S7].'))
codes=[]
def rec(v):
 if isinstance(v,dict):
  if str(v.get('code','')).startswith('E30'):codes.append(v)
  for x in v.values():rec(x)
 elif isinstance(v,list):
  for x in v:rec(x)
rec(json.loads((R/'nosology/fragments/S05.json').read_text()))
S.append(sec(13,'Tous les sous-codes et contexte suisse',table(['Code OFS local 2024','Libellé'],[[x['code'],html.escape(x['title'])] for x in codes])+'''<p>E30.0 inclut le retard constitutionnel dans les notes allemandes ; E30.8 inclut thélarche et pubarche prématurées. E30.1 ne reçoit pas par défaut une précocité centrale confirmée, qui est exclue vers E22.8 dans ces notes ; les causes surrénales ou syndromiques citées gardent leurs catégories propres [S1, S2].</p><p>La brochure suisse 2021 évoque la prise en charge par l’assurance de base. Ce propos ancien ne certifie pas un remboursement individuel 2026, une autorisation hors indication pédiatrique ou une formulation disponible. Produit, indication, durée, critères et éventuel accord sont vérifiés à la date de prescription ; aucun statut administratif individuel n’est inventé [S4, S11–S15].</p><p>Le bilan génétique et l’examen intime suivent le cadre suisse actuel de consentement et de confidentialité ; les recommandations étrangères ne créent pas à elles seules une règle légale suisse. La leçon ne prétend pas établir une obligation spécifique de déclaration ou une couverture d’assurance pour tout E30 [S5].</p>''','Le code documente le diagnostic ; il ne choisit ni traitement ni remboursement. Le contexte administratif reste daté et individualisé [S1, S2, S4].'))
S.append(sec(14,'Critères formels, paramètres et pièges','''<p><b>Critères formels.</b> Les repères cliniques sont précocité avant huit/neuf ans, absence de seins à treize ans ou d’augmentation testiculaire pubertaire à quatorze selon Endo-ERN, et progression inadéquate à tout âge pertinent. Une absence de ménarche à quinze ans avec développement, ou treize ans sans signes, mérite exploration ; l’aménorrhée peut avoir une cause différente du simple retard gonadique [S5, S7, S16].</p><p><b>Méthode et paramètres.</b> Le repère testiculaire ≥4 ml à l’orchidomètre ne remplace ni une mesure échographique ni les anciennes définitions 3/3,5 ml. Le guide allemand 2021 utilise 13,5 ans chez la fille, là où Endo-ERN recommande évaluation à treize ; on n’attend pas ce délai s’il existe progression arrêtée ou maladie. Les pics gonadotropes et leur rapport gardent méthode, timing et âge [S5, S7, S8, S10].</p><p><b>Pièges.</b> Confondre pilosité et activation centrale ; exclure la précocité par une valeur basale basse ; diagnostiquer constitutionnel sur la famille seule ; traiter une cause périphérique avec un dépôt central sans bilan ; copier l’intervalle d’une autre préparation ; commencer une dose adulte pour induire ; assimiler substitution de testostérone et restauration de fertilité ; rassurer sur tout effet indésirable d’après une brochure ancienne [S4–S7, S11–S15].</p><p>Pour l’examen, expliquer la question clinique, le test qui change la décision et le suivi est plus utile qu’un chiffre isolé. Aucun score E30 unique ni question officielle garantie n’est inventé [S20].</p>''','Le stade, la méthode et la population font partie de chaque seuil. L’incertitude appelle une exploration ou un suivi explicite, pas une conclusion automatique [S5–S8].'))
css='''[data-e30-table="1"]{font-size:inherit!important;display:block;max-width:100%;overflow-x:auto}[data-e30-table="1"] th,[data-e30-table="1"] td{font-size:inherit!important;min-width:9em}[data-e30-frame]{position:relative}[data-e30-frame] img{display:block;max-width:100%;height:auto}[data-e30-marker]{position:absolute;background:#123d4e;color:white;border:2px solid white;border-radius:50%;padding:1px 4px;font-weight:bold;font-size:clamp(8px,1vw,12px);line-height:1.2}[data-e30-pin="a1"]{left:55%;top:15%}[data-e30-pin="a2"]{left:68%;top:43%}[data-e30-pin="a3"]{left:52%;top:61%}[data-e30-pin="a4"]{left:73%;top:81%}[data-e30-pin="h1"]{left:32%;top:54%}[data-e30-pin="h2"]{left:41%;top:49%}[data-e30-pin="h3"]{left:48%;top:57%}'''
head='<template id="ch-E30"><div class="chap"><style>'+css+'</style><div class="chap-head"><div class="code">E30 · couvre E30.0, E30.1, E30.8, E30.9 · Endocrinologie et métabolisme</div><h1>Anomalies de la puberté, non classées ailleurs</h1><span class="status">Relecture Sol du 2 novembre 2026 · Sources suisses et européennes · Auto-relecture, sans validation médicale humaine</span></div><div class="tabs ui" role="tablist">'
for i,(p,t) in enumerate([('pA','Pathologie et prise en charge'),('pE','Examens complémentaires'),('pS','Sciences fondamentales spécialisées'),('pP','Pharmacologie')]):head+=f'<button role="tab" aria-controls="{p}" data-p="{p}" aria-selected="{str(i==0).lower()}">{t}</button>'
