source_by_id={s['id']:s for s in ledger}
def cite(m):
 ids=[]
 for part in m[1].split(','):
  nums=re.findall(r'S?(\d+)',part)
  if ('–' in part or '—' in part) and len(nums)==2:ids.extend('S'+str(i) for i in range(int(nums[0]),int(nums[1])+1))
  else:ids.extend('S'+n for n in nums)
 ids=list(dict.fromkeys(i for i in ids if i in source_by_id))
 return '['+', '.join(f'<a data-reference-source="1" href="{html.escape(source_by_id[i]["url"],quote=True)}" target="_blank" rel="noopener">{i}</a>' for i in ids)+']' if ids else m[0]
termmap={k:'genes' for k in ['MKRN3','DLK1','KISS1','KISS1R']};termmap.update({x['code']:'codes' for x in codes if x['code']!='E30'});termmap.update({'E22.8':'codes','Q78.1':'codes','PROFILES':'profiles','Lucrin Dépôt':'lucrin','Pamorelin LA':'pamorelin','Testoviron Dépôt':'testoviron','Testosteron-Mepha':'undecanoate','Progynova':'estradiol'})
termmap.update({'CHUV':'chuv','Endo-ERN':'europe','McCune-Albright':'syndrome'})
pat=re.compile(r'(?<![\w])('+'|'.join(re.escape(k) for k in sorted(termmap,key=len,reverse=True))+r')(?![\w])')
for p in (R/'chapters/E30').glob('*.html'):
 t=p.read_text();parts=[];protected=0;inlocal=False
 for x in re.split(r'(<[^>]+>)',t):
  if x.startswith('<'):
   if re.match(r'<template\s+data-pop=',x):inlocal=True
   if x.startswith('</template'):inlocal=False
   if re.match(r'<(?:a|button|style)(?:\s|>)',x):protected+=1
   elif re.match(r'</(?:a|button|style)',x):protected=max(0,protected-1)
   parts.append(x)
  else:
   if protected:parts.append(x);continue
   if inlocal:
    def linked(m):
     k=termmap[m[1]];sid={'genes':'S17','codes':'S2','profiles':'S20','lucrin':'S11','pamorelin':'S12','testoviron':'S13','estradiol':'S14','undecanoate':'S15','chuv':'S3','europe':'S5','syndrome':'S7'}[k]
     return '<a data-reference-source="1" href="'+source_by_id[sid]['url']+'" target="_blank" rel="noopener">'+m[1]+'</a>'
    x=pat.sub(linked,x)
   else:x=pat.sub(lambda m:('<a data-reference-source="1" href="'+source_by_id['S2' if m[1]=='E22.8' else 'S1']['url']+'" target="_blank" rel="noopener">'+m[1]+'</a>') if termmap[m[1]]=='codes' else w(termmap[m[1]],m[1]),x)
   x=re.sub(r'\[((?:S\d+)[^\[\]]*)\]',cite,x);parts.append(x)
 t=''.join(parts);t=re.sub(r'(</(?:p|section|table|template|figure|nav)>)(?=<)',r'\1\n',t);p.write_text(t)
